import java.lang.foreign.Arena;
import java.lang.foreign.ValueLayout;
import oshi.ffm.util.platform.mac.SysctlUtilFFM;

class MacMemoryCandidateProbe
{
    public static void main(String[] args)
    {
        long total = SysctlUtilFFM.sysctl("hw.memsize", -1L);
        System.out.println("total=" + total);
        if (total <= 0)
            throw new AssertionError("Physical memory query did not return a positive size");
        int pressure = SysctlUtilFFM.sysctl("kern.memorystatus_vm_pressure_level", -1);
        System.out.println("pressure=" + pressure);
        switch (pressure)
        {
            case 1, 2, 4 -> { }
            default -> throw new AssertionError("Unrecognized or unavailable pressure flag: " + pressure);
        }
        int missing = SysctlUtilFFM.sysctl("kern.codex_unleashed_absent_memory_probe", -1);
        System.out.println("missing-scalar=" + missing);
        if (missing == -1) { }
        else throw new AssertionError("Absent sysctl did not preserve the sentinel");

        try (Arena arena = Arena.ofConfined())
        {
            var swap = arena.allocate(32, 8);
            boolean success = SysctlUtilFFM.sysctl("vm.swapusage", swap);
            System.out.println("swap-success=" + success);
            if (success)
            {
                System.out.println("swap-total=" + swap.get(ValueLayout.JAVA_LONG, 0));
                System.out.println("swap-used=" + swap.get(ValueLayout.JAVA_LONG, 16));
            }
            else throw new AssertionError("Swap query failed");
            boolean absent = SysctlUtilFFM.sysctl("kern.codex_unleashed_absent_memory_probe", swap);
            System.out.println("missing-struct=" + absent);
            if (absent)
                throw new AssertionError("Absent sysctl was reported as successful");
        }
    }
}

import oshi.driver.common.windows.perfmon.PagingFile.PagingPercentProperty;
import oshi.ffm.util.platform.windows.PerfCounterQueryFFM;

class WindowsMemoryCandidateProbe
{
    public static void main(String[] args)
    {
        var used = PerfCounterQueryFFM.queryValuesFromPDH(PagingPercentProperty.class, "Paging File");
        System.out.println("paging-query=" + used);
        if (used.containsKey(PagingPercentProperty.PERCENTUSAGE))
        {
            long raw = used.get(PagingPercentProperty.PERCENTUSAGE);
            System.out.println("present-raw-usage=" + raw);
            if (raw < 0)
                throw new AssertionError("Negative paging counter: " + raw);
        }
        else throw new AssertionError("Required paging counter is missing");

        var missing = PerfCounterQueryFFM.queryValuesFromPDH(PagingPercentProperty.class,
            "CodexUnleashedAbsentMemoryProbe");
        System.out.println("absent-query=" + missing);
        if (missing.isEmpty()) { }
        else throw new AssertionError("Absent counter object was reported as successful");
    }
}

