import java.util.Objects;
import oshi.driver.common.windows.wmi.WmiQuery;
import oshi.driver.common.windows.wmi.WmiResult;
import oshi.ffm.util.platform.windows.WmiQueryExecutorFFM;

class WindowsWmiCandidateProbe
{
    enum ProcessProperty { PROCESSID, WORKINGSETSIZE, SESSIONID, TERMINATIONDATE }

    static void display(String label, WmiResult<ProcessProperty> result)
    {
        System.out.println(label + ":rows=" + result.getResultCount());
        for (int row = 0; row < result.getResultCount(); row += 1)
        {
            for (var property : ProcessProperty.values())
            {
                Object value = result.getValue(property, row);
                String type = value == null ? "null" : value.getClass().getName();
                System.out.println(label + ":" + property + "=" + value + ":java=" + type
                    + ":vt=" + result.getVtType(property) + ":cim=" + result.getCIMType(property));
            }
        }
    }

    public static void main(String[] args)
    {
        var executor = Objects.requireNonNull(WmiQueryExecutorFFM.createInstance(), "WMI executor unavailable");
        long pid = ProcessHandle.current().pid();
        var current = executor.queryWMI(new WmiQuery<>("Win32_Process WHERE ProcessId=" + pid,
            ProcessProperty.class));
        display("current", current);
        if (current.getResultCount() != 1)
            throw new AssertionError("Current process query must return exactly one row");
        Object resident = Objects.requireNonNull(current.getValue(ProcessProperty.WORKINGSETSIZE, 0),
            "Working-set query did not return a value");
        if (Long.parseLong(resident.toString()) <= 0)
            throw new AssertionError("Current Java process working set must be positive");
        Object returnedPid = Objects.requireNonNull(current.getValue(ProcessProperty.PROCESSID, 0),
            "Process ID query did not return a value");
        if (Long.parseLong(returnedPid.toString()) != pid)
            throw new AssertionError("Returned process ID differs from the requested process");
        if (current.getValue(ProcessProperty.TERMINATIONDATE, 0) != null)
            throw new AssertionError("Running process termination date must remain unavailable");

        var idle = executor.queryWMI(new WmiQuery<>("Win32_Process WHERE ProcessId=0", ProcessProperty.class));
        display("idle", idle);
        if (idle.getResultCount() != 1)
            throw new AssertionError("Idle process query must return exactly one row");
        Object zero = Objects.requireNonNull(idle.getValue(ProcessProperty.PROCESSID, 0),
            "Idle process ID is unavailable");
        if (Long.parseLong(zero.toString()) != 0)
            throw new AssertionError("Idle process ID must remain numeric zero");

        var missing = executor.queryWMI(new WmiQuery<>("CodexUnleashedAbsentWmiClass", ProcessProperty.class));
        display("missing", missing);
        if (missing.getResultCount() != 0)
            throw new AssertionError("Absent WMI class must not return measurements");
        System.out.println("WMI_CANDIDATE_PASSED");
    }
}

