import java.util.Map;
import oshi.driver.common.windows.perfmon.PdhCounterProperty;
import oshi.ffm.util.platform.windows.PerfCounterQueryFFM;

class WindowsMemoryCountersProbe
{
    enum MemoryCounter implements PdhCounterProperty
    {
        AVAILABLE, INPUT, OUTPUT, ABSENT;

        public String getInstance()
        {
            return null;
        }

        public String getCounter()
        {
            return switch (this)
            {
                case AVAILABLE -> "Available Bytes";
                case INPUT -> "Pages Input/sec";
                case OUTPUT -> "Pages Output/sec";
                case ABSENT -> "CodexUnleashedAbsentMemoryCounter";
            };
        }
    }

    public static void main(String[] args)
    {
        for (int sample = 0; sample < 8; sample++)
        {
            long started = System.nanoTime();
            Map<MemoryCounter, Long> values = PerfCounterQueryFFM.queryValuesFromPDH(
                MemoryCounter.class, "Memory");
            long elapsed = System.nanoTime() - started;
            System.out.println("sample=" + sample + ":values=" + values + ":elapsed-ns=" + elapsed);
            for (MemoryCounter required : new MemoryCounter[]{MemoryCounter.AVAILABLE,
                MemoryCounter.INPUT, MemoryCounter.OUTPUT})
            {
                if (values.containsKey(required))
                {
                    if (values.get(required) < 0)
                        throw new AssertionError("Negative memory counter: " + required);
                }
                else
                    throw new AssertionError("Required memory counter unavailable: " + required);
            }
            if (values.containsKey(MemoryCounter.ABSENT))
                throw new AssertionError("Absent memory counter was reported as available");
        }
        System.out.println("MEMORY_COUNTER_CANDIDATE_PASSED");
    }
}

