import java.lang.foreign.Arena;
import java.lang.foreign.FunctionDescriptor;
import java.lang.foreign.Linker;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.SymbolLookup;
import java.lang.foreign.ValueLayout;
import oshi.ffm.util.platform.mac.SysctlUtilFFM;

class MacMemoryNativeProbe
{
    public static void main(String[] args) throws Throwable
    {
        long total = SysctlUtilFFM.sysctl("hw.memsize", -1L);
        int pageSize = SysctlUtilFFM.sysctl("hw.pagesize", -1);
        if (total <= 0 || pageSize <= 0)
            throw new AssertionError("Physical-memory or page-size query unavailable");

        try (Arena arena = Arena.ofConfined())
        {
            var library = SymbolLookup.libraryLookup("/usr/lib/libSystem.B.dylib", arena);
            var linker = Linker.nativeLinker();
            var hostSelf = linker.downcallHandle(library.find("mach_host_self").orElseThrow(),
                FunctionDescriptor.of(ValueLayout.JAVA_INT));
            var taskSelf = linker.downcallHandle(library.find("mach_task_self").orElseThrow(),
                FunctionDescriptor.of(ValueLayout.JAVA_INT));
            var releasePort = linker.downcallHandle(library.find("mach_port_deallocate").orElseThrow(),
                FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.JAVA_INT));
            var vmStats = linker.downcallHandle(library.find("host_statistics").orElseThrow(),
                FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.JAVA_INT,
                    ValueLayout.ADDRESS, ValueLayout.ADDRESS));
            var usage = linker.downcallHandle(library.find("proc_pid_rusage").orElseThrow(),
                FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.JAVA_INT,
                    ValueLayout.ADDRESS), Linker.Option.captureCallState("errno"));
            var callStateLayout = Linker.Option.captureStateLayout();
            long errnoOffset = callStateLayout.byteOffset(java.lang.foreign.MemoryLayout.PathElement.groupElement("errno"));
            var callState = arena.allocate(callStateLayout);
            var statistics = arena.allocate(60, 4);
            var count = arena.allocate(ValueLayout.JAVA_INT);
            var process = arena.allocate(160, 8);
            int pid = Math.toIntExact(ProcessHandle.current().pid());
            int task = (int) taskSelf.invokeExact();
            int host = (int) hostSelf.invokeExact();
            if (host == 0)
                throw new AssertionError("Native host port unavailable");

            try
            {
                for (int sample = 0; sample < 16; sample++)
                {
                    long started = System.nanoTime();
                    count.set(ValueLayout.JAVA_INT, 0, 15);
                    int vmStatus = (int) vmStats.invokeExact(host, 2, statistics, count);
                    if (vmStatus != 0)
                        throw new AssertionError("Host statistics query failed: " + vmStatus);
                    if (count.get(ValueLayout.JAVA_INT, 0) < 3)
                        throw new AssertionError("Host statistics result lacks required page fields");
                    long freePages = Integer.toUnsignedLong(statistics.get(ValueLayout.JAVA_INT, 0));
                    long inactivePages = Integer.toUnsignedLong(statistics.get(ValueLayout.JAVA_INT, 8));
                    long available = Math.multiplyExact(Math.addExact(freePages, inactivePages), pageSize);
                    if (available > total)
                        throw new AssertionError("Available-memory estimate exceeds physical memory");
                    int processStatus = (int) usage.invokeExact(callState, pid, 2, process);
                    if (processStatus != 0)
                        throw new AssertionError("Process memory query failed: " + callState.get(ValueLayout.JAVA_INT, errnoOffset));
                    long resident = process.get(ValueLayout.JAVA_LONG, 64);
                    if (resident <= 0)
                        throw new AssertionError("Self resident-memory query did not return positive bytes");
                    int pressure = SysctlUtilFFM.sysctl("kern.memorystatus_vm_pressure_level", -1);
                    switch (pressure)
                    {
                        case 1, 2, 4 -> { }
                        default -> throw new AssertionError("Memory pressure query unavailable: " + pressure);
                    }
                    long elapsed = System.nanoTime() - started;
                    System.out.println("sample=" + sample + ":available=" + available + ":resident=" + resident
                        + ":page-size=" + pageSize + ":pressure=" + pressure + ":elapsed-ns=" + elapsed);
                }

                count.set(ValueLayout.JAVA_INT, 0, 15);
                int invalidVm = (int) vmStats.invokeExact(host, -1, statistics, count);
                int missingProcess = (int) usage.invokeExact(callState, Integer.MAX_VALUE, 2, process);
                int missingErrno = callState.get(ValueLayout.JAVA_INT, errnoOffset);
                System.out.println("invalid-vm-status=" + invalidVm + ":missing-process-status=" + missingProcess
                    + ":missing-process-errno=" + missingErrno);
                if (invalidVm == 0 || missingProcess == 0)
                    throw new AssertionError("Invalid native query was accepted as a successful measurement");
            }
            finally
            {
                int released = (int) releasePort.invokeExact(task, host);
                if (released != 0)
                    throw new AssertionError("Host port release failed: " + released);
                System.out.println("host-port-release=0");
            }
        }
        System.out.println("MAC_MEMORY_NATIVE_CANDIDATE_PASSED");
    }
}

