import java.lang.foreign.Arena;
import java.lang.foreign.FunctionDescriptor;
import java.lang.foreign.Linker;
import java.lang.foreign.MemoryLayout;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.SymbolLookup;
import java.lang.foreign.ValueLayout;
import oshi.driver.common.windows.perfmon.PagingFile.PagingPercentProperty;
import oshi.ffm.util.platform.windows.PerfCounterQueryFFM;

class WindowsPagefileGrowthProbe
{
    static void sample(String phase, int count) throws InterruptedException
    {
        for (int sample = 0; sample < count; sample++)
        {
            var occupancy = PerfCounterQueryFFM.queryValuesFromPDH(
                PagingPercentProperty.class, "Paging File");
            System.out.println("phase=" + phase + ":sample=" + sample + ":present="
                + occupancy.containsKey(PagingPercentProperty.PERCENTUSAGE)
                + ":raw-pages=" + occupancy.get(PagingPercentProperty.PERCENTUSAGE));
            Thread.sleep(250);
        }
    }

    public static void main(String[] args) throws Throwable
    {
        try (var nativeCalls = Arena.ofConfined())
        {
            var kernel = SymbolLookup.libraryLookup("Kernel32.dll", nativeCalls);
            var linker = Linker.nativeLinker();
            var currentProcess = linker.downcallHandle(kernel.find("GetCurrentProcess").orElseThrow(),
                FunctionDescriptor.of(ValueLayout.ADDRESS));
            MemorySegment process = (MemorySegment) currentProcess.invokeExact();
            var trim = linker.downcallHandle(kernel.find("K32EmptyWorkingSet").orElseThrow(),
                FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.ADDRESS),
                Linker.Option.captureCallState("GetLastError"));
            var errorLayout = Linker.Option.captureStateLayout();
            var errors = nativeCalls.allocate(errorLayout);
            long errorOffset = errorLayout.byteOffset(MemoryLayout.PathElement.groupElement("GetLastError"));
            sample("baseline", 4);

            try (var allocation = Arena.ofConfined())
            {
                long allocationBytes = 256L * 1024 * 1024;
                var payload = allocation.allocate(allocationBytes, 4096);
                var random = new java.util.Random(0L);
                var chunk = new byte[1024 * 1024];
                for (long offset = 0; offset < allocationBytes; offset += chunk.length)
                {
                    random.nextBytes(chunk);
                    payload.asSlice(offset, chunk.length).copyFrom(MemorySegment.ofArray(chunk));
                }
                int result = (int) trim.invokeExact(errors, process);
                System.out.println("trim-result=" + result + ":last-error="
                    + errors.get(ValueLayout.JAVA_INT, errorOffset) + ":allocated-bytes=" + allocationBytes);
                sample("allocated-and-trimmed", 40);
            }

            sample("released", 40);
        }
    }
}

