import java.lang.foreign.Arena;
import java.lang.foreign.FunctionDescriptor;
import java.lang.foreign.Linker;
import java.lang.foreign.MemoryLayout;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.SymbolLookup;
import java.lang.foreign.ValueLayout;

class WindowsPressureCandidateProbe
{
    public static void main(String[] args) throws Throwable
    {
        try (var arena = Arena.ofConfined())
        {
            var kernel = SymbolLookup.libraryLookup("Kernel32.dll", arena);
            var linker = Linker.nativeLinker();
            var captureError = Linker.Option.captureCallState("GetLastError");
            var create = linker.downcallHandle(kernel.find("CreateMemoryResourceNotification").orElseThrow(),
                FunctionDescriptor.of(ValueLayout.ADDRESS, ValueLayout.JAVA_INT), captureError);
            var query = linker.downcallHandle(kernel.find("QueryMemoryResourceNotification").orElseThrow(),
                FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.ADDRESS, ValueLayout.ADDRESS), captureError);
            var close = linker.downcallHandle(kernel.find("CloseHandle").orElseThrow(),
                FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.ADDRESS), captureError);
            var errorLayout = Linker.Option.captureStateLayout();
            var errors = arena.allocate(errorLayout);
            long errorOffset = errorLayout.byteOffset(MemoryLayout.PathElement.groupElement("GetLastError"));
            var pressure = arena.allocate(ValueLayout.JAVA_INT);

            MemorySegment handle = (MemorySegment) create.invokeExact(errors, 0);
            if (handle.address() == 0)
                throw new AssertionError("Low-memory notification creation failed: "
                    + errors.get(ValueLayout.JAVA_INT, errorOffset));
            try
            {
                for (int sample = 0; sample < 8; sample++)
                {
                    pressure.set(ValueLayout.JAVA_INT, 0, -1);
                    int result = (int) query.invokeExact(errors, handle, pressure);
                    System.out.println("sample=" + sample + ":query-result=" + result + ":pressure="
                        + pressure.get(ValueLayout.JAVA_INT, 0) + ":last-error="
                        + errors.get(ValueLayout.JAVA_INT, errorOffset));
                }

                pressure.set(ValueLayout.JAVA_INT, 0, -1);
                int missing = (int) query.invokeExact(errors, MemorySegment.NULL, pressure);
                System.out.println("invalid-handle:query-result=" + missing + ":pressure-buffer="
                    + pressure.get(ValueLayout.JAVA_INT, 0) + ":last-error="
                    + errors.get(ValueLayout.JAVA_INT, errorOffset));
            }
            finally
            {
                int result = (int) close.invokeExact(errors, handle);
                System.out.println("close-result=" + result + ":last-error="
                    + errors.get(ValueLayout.JAVA_INT, errorOffset));
            }

            MemorySegment invalid = (MemorySegment) create.invokeExact(errors, -1);
            System.out.println("invalid-type:handle=" + invalid.address() + ":last-error="
                + errors.get(ValueLayout.JAVA_INT, errorOffset));
            if (invalid.address() == 0)
                System.out.println("Invalid notification type rejected");
            else
            {
                int result = (int) close.invokeExact(errors, invalid);
                System.out.println("unexpected-handle-close-result=" + result);
            }
        }
    }
}

