package com.holdmyspot.codexunleashed.scheduler;

import java.io.IOException;
import java.io.Reader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Properties;
import java.util.Scanner;

/**
 * Reads Linux host memory counters without controlling processes or machine configuration.
 * <p>
 * This sampler requires MemAvailable and memory PSI support. Measurements are host-wide, acquired sequentially and
 * not an atomic snapshot. The controller must separately account for cgroup limits and owned process-tree residency.
 * Cumulative activity counters require comparison between samples; their absolute values do not describe current
 * pressure. Independent calls own their readers and share no mutable state.
 */
public final class LinuxMemory
{
	/**
	 * Prevents construction of this stateless sampler.
	 */
	private LinuxMemory()
	{
	}

	/**
	 * Represents nonnegative host memory and cumulative activity measurements.
	 *
	 * @param totalBytes positive usable physical bytes
	 * @param availableBytes estimated physical bytes available for new work without swapping, at most totalBytes
	 * @param swapTotalBytes configured swap capacity in bytes
	 * @param swapUsedBytes occupied swap bytes, at most swapTotalBytes
	 * @param swapOutPages cumulative pages written to swap since boot
	 * @param stallMicros cumulative microseconds during which at least some tasks stalled on memory
	 */
	public record Sample(long totalBytes, long availableBytes, long swapTotalBytes, long swapUsedBytes,
		long swapOutPages, long stallMicros)
	{
		/**
		 * Creates a validated set of host counters.
		 *
		 * @param totalBytes positive usable physical bytes
		 * @param availableBytes nonnegative available physical bytes, at most totalBytes
		 * @param swapTotalBytes nonnegative swap capacity in bytes
		 * @param swapUsedBytes nonnegative occupied swap bytes, at most swapTotalBytes
		 * @param swapOutPages nonnegative cumulative pages written to swap
		 * @param stallMicros nonnegative cumulative memory stall microseconds
		 * @throws IllegalArgumentException if a count is negative, {@code totalBytes} is zero,
		 * {@code availableBytes} exceeds {@code totalBytes}, or {@code swapUsedBytes} exceeds {@code swapTotalBytes}
		 */
		public Sample
		{
			if (totalBytes <= 0)
				throw new IllegalArgumentException("totalBytes must be positive; received " + totalBytes);
			if (availableBytes < 0 || swapTotalBytes < 0 || swapUsedBytes < 0 || swapOutPages < 0 || stallMicros < 0)
				throw new IllegalArgumentException("Memory and activity counts must be nonnegative");
			if (availableBytes > totalBytes)
				throw new IllegalArgumentException("availableBytes exceeds totalBytes: " + availableBytes + " > " + totalBytes);
			if (swapUsedBytes > swapTotalBytes)
				throw new IllegalArgumentException("swapUsedBytes exceeds swapTotalBytes: " + swapUsedBytes + " > " + swapTotalBytes);
		}
	}

	/**
	 * Reads meminfo, vmstat and pressure/memory below a supplied Linux proc filesystem root.
	 * <p>
	 * Kernel kB values are converted to bytes using 1,024 bytes per unit. Missing or failed observations are reported
	 * as failures rather than zero activity. PSI's some-total microseconds and vmstat's pswpout pages remain cumulative.
	 *
	 * @param procRoot the nonnull proc filesystem root, normally /proc, supplied by the runtime boundary
	 * @return the host memory counters; zero swap occupancy is valid when the required observations report it
	 * @throws NullPointerException if {@code procRoot} is null
	 * @throws IOException if a required file cannot be read, a required counter is absent, its count or unit is
	 * invalid, byte conversion overflows, or the resulting measurements are inconsistent
	 */
	public static Sample read(Path procRoot) throws IOException
	{
		Path meminfo = procRoot.resolve("meminfo");
		Properties memory = readCounters(meminfo);
		long total = readBytes(memory, meminfo, "MemTotal");
		long available = readBytes(memory, meminfo, "MemAvailable");
		long swapTotal = readBytes(memory, meminfo, "SwapTotal");
		long swapFree = readBytes(memory, meminfo, "SwapFree");
		if (swapFree > swapTotal)
			throw new IOException("SwapFree exceeds SwapTotal in " + meminfo);

		Path vmstat = procRoot.resolve("vmstat");
		Properties activity = readCounters(vmstat);
		long swapOut = readCount(requireCounter(activity, vmstat, "pswpout"), vmstat, "pswpout");
		Path pressure = procRoot.resolve("pressure/memory");
		long stalls = readStallMicros(readCounters(pressure), pressure);
		try
		{
			return new Sample(total, available, swapTotal, swapTotal - swapFree, swapOut, stalls);
		}
		catch (IllegalArgumentException failure)
		{
			throw new IOException("Inconsistent memory measurements below " + procRoot + ": " + failure.getMessage(), failure);
		}
	}

	/**
	 * Reads colon or whitespace-separated kernel counter records with the Java properties reader.
	 *
	 * @param source the kernel counter file
	 * @return the file's key/value records
	 * @throws IOException if {@code source} cannot be read or contains invalid property escapes
	 */
	private static Properties readCounters(Path source) throws IOException
	{
		Properties counters = new Properties();
		try (Reader input = Files.newBufferedReader(source))
		{
			counters.load(input);
		}
		catch (IllegalArgumentException failure)
		{
			throw new IOException("Invalid counter records in " + source, failure);
		}
		return counters;
	}

	/**
	 * Requires a named kernel counter before interpreting its value.
	 *
	 * @param counters the file's key/value records
	 * @param source the kernel counter file for diagnostics
	 * @param name the required counter name
	 * @return the trimmed counter value
	 * @throws IOException if {@code name} is absent
	 */
	private static String requireCounter(Properties counters, Path source, String name) throws IOException
	{
		String value = counters.getProperty(name);
		if (value == null)
			throw new IOException("Missing " + name + " counter in " + source);
		return value.strip();
	}

	/**
	 * Converts a named kB memory counter to an exact byte count.
	 *
	 * @param counters the meminfo records
	 * @param source the meminfo file for diagnostics
	 * @param name the required memory counter
	 * @return its nonnegative byte count
	 * @throws IOException if {@code name} is absent, lacks its kB unit, has an invalid count, or overflows bytes
	 */
	private static long readBytes(Properties counters, Path source, String name) throws IOException
	{
		String value = requireCounter(counters, source, name);
		String[] parts = value.split("\\s+");
		if (parts.length != 2 || parts[1].equals("kB") == false)
			throw new IOException("Expected a count followed by kB for " + name + " in " + source + "; received " + value);
		long kibibytes = readCount(parts[0], source, name);
		try
		{
			return Math.multiplyExact(kibibytes, 1024);
		}
		catch (ArithmeticException failure)
		{
			throw new IOException("Byte conversion overflows for " + name + " in " + source + "; received " + value, failure);
		}
	}

	/**
	 * Reads the cumulative some-total memory stall time without interpreting it as current pressure.
	 *
	 * @param counters the PSI records
	 * @param source the PSI file for diagnostics
	 * @return the nonnegative cumulative stall microseconds
	 * @throws IOException if the some record or its total is absent, or the total count is invalid
	 */
	private static long readStallMicros(Properties counters, Path source) throws IOException
	{
		try (Scanner fields = new Scanner(requireCounter(counters, source, "some")))
		{
			while (fields.hasNext())
			{
				String field = fields.next();
				if (field.startsWith("total="))
					return readCount(field.substring("total=".length()), source, "some.total");
			}
		}
		throw new IOException("Missing some.total counter in " + source);
	}

	/**
	 * Parses a nonnegative integer kernel counter without substituting a fallback value on failure.
	 *
	 * @param value the integer text
	 * @param source the kernel counter file for diagnostics
	 * @param name the counter name
	 * @return the nonnegative count
	 * @throws IOException if {@code value} is negative or cannot be represented by a long
	 */
	private static long readCount(String value, Path source, String name) throws IOException
	{
		try
		{
			long count = Long.parseLong(value);
			if (count < 0)
				throw new IOException("Negative " + name + " counter in " + source + "; received " + value);
			return count;
		}
		catch (NumberFormatException failure)
		{
			throw new IOException("Invalid integer for " + name + " in " + source + "; received " + value, failure);
		}
	}
}

linux_public_operation_failure_gate.driver_source:
import com.holdmyspot.codexunleashed.scheduler.LinuxMemory;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Comparator;
import java.util.List;
import java.util.Map;

class FailureGate
{
    public static void main(String[] args) throws Exception
    {
        Path fixtureParent = Path.of(args[0]);
        Map<String, String> baseline = Map.of(
            "meminfo", "MemTotal: 4096 kB\nMemAvailable: 2048 kB\nSwapTotal: 1024 kB\nSwapFree: 1024 kB\n",
            "vmstat", "pswpout 0\n",
            "pressure/memory", "some avg10=0.00 avg60=0.00 avg300=0.00 total=0\n");
        List<Map<String, String>> cases = List.of(
            Map.of("name", "missing-available", "file", "meminfo", "body", baseline.get("meminfo").replace("MemAvailable: 2048 kB\n", ""), "diagnostic", "MemAvailable"),
            Map.of("name", "missing-swapout", "file", "vmstat", "body", "pgpgout 0\n", "diagnostic", "pswpout"),
            Map.of("name", "missing-stall-total", "file", "pressure/memory", "body", "some avg10=0.00\n", "diagnostic", "some.total"),
            Map.of("name", "wrong-unit", "file", "meminfo", "body", baseline.get("meminfo").replace("2048 kB", "2048 MB"), "diagnostic", "MemAvailable"),
            Map.of("name", "negative-swapout", "file", "vmstat", "body", "pswpout -1\n", "diagnostic", "pswpout"),
            Map.of("name", "byte-overflow", "file", "meminfo", "body", baseline.get("meminfo").replace("4096 kB", "9223372036854775807 kB"), "diagnostic", "MemTotal"),
            Map.of("name", "available-exceeds-total", "file", "meminfo", "body", baseline.get("meminfo").replace("2048 kB", "8192 kB"), "diagnostic", "availableBytes"),
            Map.of("name", "swap-free-exceeds-total", "file", "meminfo", "body", baseline.get("meminfo").replace("SwapFree: 1024", "SwapFree: 2048"), "diagnostic", "SwapFree"),
            Map.of("name", "malformed-total", "file", "pressure/memory", "body", "some avg10=0.00 total=unknown\n", "diagnostic", "some.total"));

        for (Map<String, String> test : cases)
        {
            Path procRoot = Files.createTempDirectory(fixtureParent, test.get("name") + "-");
            try
            {
                for (var counterFile : baseline.entrySet())
                {
                    Path file = procRoot.resolve(counterFile.getKey());
                    Files.createDirectories(file.getParent());
                    Files.writeString(file, counterFile.getValue());
                }
                Files.writeString(procRoot.resolve(test.get("file")), test.get("body"));
                try
                {
                    var sample = LinuxMemory.read(procRoot);
                    throw new AssertionError(test.get("name") + " unexpectedly returned " + sample);
                }
                catch (IOException expected)
                {
                    if (expected.getMessage().contains(test.get("diagnostic")) == false)
                        throw new AssertionError("Missing counter context for " + test.get("name"), expected);
                    System.out.println(test.get("name") + ": " + expected.getClass().getSimpleName() + ": " + expected.getMessage());
                }
            }
            finally
            {
                try (var paths = Files.walk(procRoot))
                {
                    for (Path path : paths.sorted(Comparator.reverseOrder()).toList())
                        Files.delete(path);
                }
            }
        }
        System.out.println("PASS: all nine invalid observation cases rejected; all fixture directories removed");
    }
}

linux_production_reader.test_source:
package com.holdmyspot.codexunleashed.scheduler;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import org.apache.commons.io.FileUtils;
import org.testng.annotations.DataProvider;
import org.testng.annotations.Test;
import static org.testng.Assert.assertEquals;
import static org.testng.Assert.assertTrue;
import static org.testng.Assert.expectThrows;

/**
 * Exercises Linux host-counter interpretation using isolated files representing the proc filesystem.
 */
public final class LinuxMemoryTest
{
	/**
	 * Creates host-counter behavior tests.
	 */
	public LinuxMemoryTest()
	{
	}

	/**
	 * Uses available physical memory rather than free memory and retains exact units and cumulative activity.
	 *
	 * @throws IOException if fixture setup, sampling or cleanup fails
	 */
	@Test
	public void readsHostCounters() throws IOException
	{
		Path procRoot = Files.createTempDirectory("linux-memory-");
		try
		{
			writeCounters(procRoot, "MemTotal: 8192 kB\nMemFree: 1 kB\nMemAvailable: 4096 kB\n" +
				"SwapTotal: 2048 kB\nSwapFree: 512 kB\n", "pswpout 123\n",
				"some avg10=0.00 avg60=0.00 avg300=0.00 total=456\n");
			assertEquals(LinuxMemory.read(procRoot),
				new LinuxMemory.Sample(8388608, 4194304, 2097152, 1572864, 123, 456));
		}
		finally
		{
			FileUtils.deleteDirectory(procRoot.toFile());
		}
	}

	/**
	 * Preserves successful zero availability, disabled swap and zero activity without treating them as missing.
	 *
	 * @throws IOException if fixture setup, sampling or cleanup fails
	 */
	@Test
	public void preservesValidZeroCounters() throws IOException
	{
		Path procRoot = Files.createTempDirectory("linux-memory-zero-");
		try
		{
			writeCounters(procRoot, "MemTotal: 1 kB\nMemAvailable: 0 kB\nSwapTotal: 0 kB\nSwapFree: 0 kB\n",
				"pswpout 0\n", "some avg10=0.00 avg60=0.00 avg300=0.00 total=0\n");
			assertEquals(LinuxMemory.read(procRoot), new LinuxMemory.Sample(1024, 0, 0, 0, 0, 0));
		}
		finally
		{
			FileUtils.deleteDirectory(procRoot.toFile());
		}
	}

	/**
	 * Supplies missing, malformed, overflowing and inconsistent kernel observations and their diagnostic context.
	 *
	 * @return counter filename, replacement contents or null for an absent file, and the required diagnostic context
	 */
	@DataProvider
	public Object[][] invalidObservations()
	{
		String memory = "MemTotal: 4096 kB\nMemAvailable: 2048 kB\nSwapTotal: 1024 kB\nSwapFree: 1024 kB\n";
		return new Object[][] {
			{Path.of("meminfo"), memory.replace("MemAvailable: 2048 kB\n", ""), "MemAvailable"},
			{Path.of("vmstat"), "pgpgout 0\n", "pswpout"},
			{Path.of("pressure/memory"), "some avg10=0.00\n", "some.total"},
			{Path.of("meminfo"), memory.replace("2048 kB", "2048 MB"), "MemAvailable"},
			{Path.of("vmstat"), "pswpout -1\n", "pswpout"},
			{Path.of("meminfo"), memory.replace("4096 kB", "9223372036854775807 kB"), "MemTotal"},
			{Path.of("meminfo"), memory.replace("2048 kB", "8192 kB"), "availableBytes"},
			{Path.of("meminfo"), memory.replace("SwapFree: 1024", "SwapFree: 2048"), "SwapFree"},
			{Path.of("pressure/memory"), "some avg10=0.00 total=unknown\n", "some.total"},
			{Path.of("meminfo"), memory.replace("4096 kB", "0 kB"), "totalBytes"},
			{Path.of("pressure/memory"), null, "pressure"}
		};
	}

	/**
	 * Rejects unavailable or invalid observations rather than returning a plausible zero sample.
	 *
	 * @param counterFile the relative kernel counter filename
	 * @param contents replacement contents, or null to remove the file
	 * @param diagnostic the counter or source that the exception must identify
	 * @throws IOException if fixture setup or cleanup fails
	 */
	@Test(dataProvider = "invalidObservations")
	public void rejectsInvalidObservations(Path counterFile, String contents, String diagnostic) throws IOException
	{
		Path procRoot = Files.createTempDirectory("linux-memory-invalid-");
		try
		{
			writeCounters(procRoot,
				"MemTotal: 4096 kB\nMemAvailable: 2048 kB\nSwapTotal: 1024 kB\nSwapFree: 1024 kB\n",
				"pswpout 0\n", "some avg10=0.00 total=0\n");
			Path source = procRoot.resolve(counterFile);
			if (contents == null)
				Files.delete(source);
			else
				Files.writeString(source, contents);

			IOException failure = expectThrows(IOException.class, () -> LinuxMemory.read(procRoot));
			assertTrue(failure.getMessage().contains(diagnostic), failure.getMessage());
		}
		finally
		{
			FileUtils.deleteDirectory(procRoot.toFile());
		}
	}

	/**
	 * Requires a proc filesystem root supplied by the runtime boundary.
	 */
	@Test
	public void rejectsNullRoot()
	{
		expectThrows(NullPointerException.class, () -> LinuxMemory.read(null));
	}

	/**
	 * Creates the kernel records consumed by the public sampling operation.
	 *
	 * @param procRoot the test-owned directory representing the proc filesystem
	 * @param memory meminfo records
	 * @param activity vmstat records
	 * @param pressure memory PSI records
	 * @throws IOException if a fixture cannot be written
	 */
	private static void writeCounters(Path procRoot, String memory, String activity, String pressure) throws IOException
	{
		Files.createDirectories(procRoot.resolve("pressure"));
		Files.writeString(procRoot.resolve("meminfo"), memory);
		Files.writeString(procRoot.resolve("vmstat"), activity);
		Files.writeString(procRoot.resolve("pressure/memory"), pressure);
	}
}

windows_physical_candidate.source:
import java.lang.foreign.Arena;
import java.lang.foreign.FunctionDescriptor;
import java.lang.foreign.Linker;
import java.lang.foreign.MemoryLayout;
import java.lang.foreign.SymbolLookup;
import java.lang.foreign.ValueLayout;

/**
 * Checks status-preserving acquisition of physical memory and page size on native 64-bit Windows.
 */
class WindowsPhysicalCandidateProbe
{
    /**
     * Matches the Windows SDK's 64-bit PERFORMANCE_INFORMATION structure, including ABI padding.
     */
    private static final MemoryLayout PERFORMANCE_INFORMATION = MemoryLayout.structLayout(
        ValueLayout.JAVA_INT.withName("cb"), MemoryLayout.paddingLayout(4),
        ValueLayout.JAVA_LONG.withName("CommitTotal"), ValueLayout.JAVA_LONG.withName("CommitLimit"),
        ValueLayout.JAVA_LONG.withName("CommitPeak"), ValueLayout.JAVA_LONG.withName("PhysicalTotal"),
        ValueLayout.JAVA_LONG.withName("PhysicalAvailable"), ValueLayout.JAVA_LONG.withName("SystemCache"),
        ValueLayout.JAVA_LONG.withName("KernelTotal"), ValueLayout.JAVA_LONG.withName("KernelPaged"),
        ValueLayout.JAVA_LONG.withName("KernelNonpaged"), ValueLayout.JAVA_LONG.withName("PageSize"),
        ValueLayout.JAVA_INT.withName("HandleCount"), ValueLayout.JAVA_INT.withName("ProcessCount"),
        ValueLayout.JAVA_INT.withName("ThreadCount"), MemoryLayout.paddingLayout(4));

    /**
     * Requires successful physical observations and a separately reported invalid-size failure.
     *
     * @param args unused
     * @throws Throwable if native linkage, acquisition or an assertion fails
     */
    public static void main(String[] args) throws Throwable
    {
        if (ValueLayout.ADDRESS.byteSize() != 8)
            throw new AssertionError("This candidate requires a 64-bit Windows process");
        try (var arena = Arena.ofConfined())
        {
            var kernel = SymbolLookup.libraryLookup("Kernel32.dll", arena);
            var getInfo = Linker.nativeLinker().downcallHandle(kernel.find("K32GetPerformanceInfo").orElseThrow(),
                FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.ADDRESS, ValueLayout.JAVA_INT),
                Linker.Option.captureCallState("GetLastError"));
            var errors = arena.allocate(Linker.Option.captureStateLayout());
            long errorOffset = Linker.Option.captureStateLayout().byteOffset(
                MemoryLayout.PathElement.groupElement("GetLastError"));
            var info = arena.allocate(PERFORMANCE_INFORMATION);
            int size = Math.toIntExact(PERFORMANCE_INFORMATION.byteSize());
            info.set(ValueLayout.JAVA_INT, 0, size);
            System.out.println("java=" + System.getProperty("java.version") + ":arch="
                + System.getProperty("os.arch") + ":struct-bytes=" + size);

            for (int sample = 0; sample < 4; sample++)
            {
                int status = (int) getInfo.invokeExact(errors, info, size);
                if (status == 0)
                    throw new AssertionError("K32GetPerformanceInfo failed: "
                        + errors.get(ValueLayout.JAVA_INT, errorOffset));
                long pageBytes = info.get(ValueLayout.JAVA_LONG, 80);
                long totalPages = info.get(ValueLayout.JAVA_LONG, 32);
                long availablePages = info.get(ValueLayout.JAVA_LONG, 40);
                long totalBytes = Math.multiplyExact(totalPages, pageBytes);
                long availableBytes = Math.multiplyExact(availablePages, pageBytes);
                if (pageBytes <= 0 || totalBytes <= 0 || availableBytes < 0 || availableBytes > totalBytes)
                    throw new AssertionError("Invalid physical counters: " + pageBytes + ":" + totalBytes
                        + ":" + availableBytes);
                System.out.println("sample=" + sample + ":status=" + status + ":page-bytes=" + pageBytes
                    + ":total-bytes=" + totalBytes + ":available-bytes=" + availableBytes);
            }

            int invalid = (int) getInfo.invokeExact(errors, info, 0);
            int error = errors.get(ValueLayout.JAVA_INT, errorOffset);
            if (invalid != 0 || error == 0)
                throw new AssertionError("Invalid-size query did not report native failure: " + invalid + ":" + error);
            System.out.println("invalid-size:status=" + invalid + ":last-error=" + error);
            System.out.println("WINDOWS_PHYSICAL_CANDIDATE_PASSED");
        }
    }
}

macos_public_operation.source:
package com.holdmyspot.codexunleashed.scheduler;

import java.io.IOException;
import java.lang.foreign.Arena;
import java.lang.foreign.FunctionDescriptor;
import java.lang.foreign.Linker;
import java.lang.foreign.SymbolLookup;
import java.lang.foreign.ValueLayout;
import java.lang.invoke.MethodHandle;
import oshi.ffm.util.platform.mac.SysctlUtilFFM;

/**
 * Reads macOS host-memory counters while preserving unavailable measurements as failures.
 * Calls own independent native scopes and share no mutable sampling state.
 */
public final class MacMemory
{
	/**
	 * Prevents construction of this stateless reader.
	 */
	private MacMemory()
	{
	}

	/**
	 * Represents the native memory-pressure notification level.
	 */
	public enum Pressure
	{
		/** The native notification level is normal. */
		NORMAL,
		/** The native notification level is warning. */
		WARNING,
		/** The native notification level is critical. */
		CRITICAL
	}

	/**
	 * Holds sequential host observations; the fields do not represent an atomic kernel snapshot.
	 *
	 * @param totalBytes the positive physical-memory capacity in bytes
	 * @param availableBytes the nonnegative free-plus-inactive estimate in bytes, at most physical capacity
	 * @param swapTotalBytes the nonnegative configured swap capacity in bytes
	 * @param swapUsedBytes the nonnegative actual swap occupancy in bytes, at most swap capacity
	 * @param pressure the acquired native memory-pressure notification level
	 */
	public record Sample(long totalBytes, long availableBytes, long swapTotalBytes, long swapUsedBytes,
		Pressure pressure)
	{
	}

	/**
	 * Reads physical memory, actual swap occupancy and native pressure on 64-bit macOS.
	 * A successful zero swap capacity is retained. Every acquired host-port send right is released before return,
	 * including when another query fails; cleanup failure prevents a successful return.
	 *
	 * @return a complete host-memory sample
	 * @throws UnsupportedOperationException if the platform or a required native symbol is unsupported
	 * @throws IOException if acquisition, native cleanup, counter validation or exact arithmetic fails
	 */
	public static Sample read() throws IOException
	{
		if (!System.getProperty("os.name", "").startsWith("Mac"))
			throw new UnsupportedOperationException("MacMemory requires macOS");

		long totalBytes = SysctlUtilFFM.sysctl("hw.memsize", -1L);
		int pageBytes = SysctlUtilFFM.sysctl("hw.pagesize", -1);
		if (totalBytes <= 0)
			throw new IOException("hw.memsize must return positive physical bytes: " + totalBytes);
		if (pageBytes <= 0)
			throw new IOException("hw.pagesize must return a positive page size: " + pageBytes);

		try (Arena arena = Arena.ofConfined())
		{
			var library = SymbolLookup.libraryLookup("/usr/lib/libSystem.B.dylib", arena);
			var hostSelf = bind(library, "mach_host_self", FunctionDescriptor.of(ValueLayout.JAVA_INT));
			var taskSelf = bind(library, "mach_task_self", FunctionDescriptor.of(ValueLayout.JAVA_INT));
			var release = bind(library, "mach_port_deallocate",
				FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.JAVA_INT));
			var statisticsQuery = bind(library, "host_statistics", FunctionDescriptor.of(ValueLayout.JAVA_INT,
				ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.ADDRESS, ValueLayout.ADDRESS));
			int task = invoke("mach_task_self", taskSelf);
			int host = invoke("mach_host_self", hostSelf);
			if (host == 0)
				throw new IOException("mach_host_self returned a null host port");

			try (HostPort port = new HostPort(release, task, host))
			{
				var statistics = arena.allocate(60, 4);
				var count = arena.allocate(ValueLayout.JAVA_INT);
				count.set(ValueLayout.JAVA_INT, 0, 15);
				int status = invoke("host_statistics", statisticsQuery, host, 2, statistics, count);
				if (status != 0)
					throw new IOException("host_statistics failed with Mach status " + status);
				int returnedCount = count.get(ValueLayout.JAVA_INT, 0);
				if (returnedCount < 3)
					throw new IOException("host_statistics returned fewer than three required fields: " + returnedCount);
				long freePages = Integer.toUnsignedLong(statistics.get(ValueLayout.JAVA_INT, 0));
				long inactivePages = Integer.toUnsignedLong(statistics.get(ValueLayout.JAVA_INT, 8));
				long availableBytes = Math.multiplyExact(Math.addExact(freePages, inactivePages), pageBytes);
				if (availableBytes > totalBytes)
					throw new IOException("Available physical bytes exceed total bytes: " + availableBytes + ">" + totalBytes);

				var swap = arena.allocate(32, 8);
				if (!SysctlUtilFFM.sysctl("vm.swapusage", swap))
					throw new IOException("vm.swapusage acquisition failed");
				long swapTotalBytes = swap.get(ValueLayout.JAVA_LONG, 0);
				long swapUsedBytes = swap.get(ValueLayout.JAVA_LONG, 16);
				if (swapTotalBytes < 0 || swapUsedBytes < 0 || swapUsedBytes > swapTotalBytes)
					throw new IOException("Swap capacities require 0 <= used <= total bytes: " +
						swapUsedBytes + "/" + swapTotalBytes);

				int pressureFlag = SysctlUtilFFM.sysctl("kern.memorystatus_vm_pressure_level", -1);
				Pressure pressure = switch (pressureFlag)
				{
					case 1 -> Pressure.NORMAL;
					case 2 -> Pressure.WARNING;
					case 4 -> Pressure.CRITICAL;
					default -> throw new IOException("Unsupported native memory-pressure flag: " + pressureFlag);
				};
				return new Sample(totalBytes, availableBytes, swapTotalBytes, swapUsedBytes, pressure);
			}
		}
		catch (ArithmeticException e)
		{
			throw new IOException("Native memory counters exceed the signed 64-bit byte range", e);
		}
	}

	/**
	 * Binds a required macOS system-library function with its accepted native ABI.
	 *
	 * @param library the library lookup owned by the current call's native scope
	 * @param name the required native symbol
	 * @param descriptor the function's native return and argument layouts
	 * @return the bound native function
	 * @throws UnsupportedOperationException if the required symbol is absent
	 */
	private static MethodHandle bind(SymbolLookup library, String name, FunctionDescriptor descriptor)
	{
		var symbol = library.find(name).orElseThrow(() ->
			new UnsupportedOperationException("Required macOS native symbol is absent: " + name));
		return Linker.nativeLinker().downcallHandle(symbol, descriptor);
	}

	/**
	 * Invokes an integer-returning native function without discarding checked invocation failures.
	 *
	 * @param operation the native operation identified in a checked failure
	 * @param function the bound function
	 * @param arguments the function's native arguments
	 * @return the native integer result, including any operation-specific failure status
	 * @throws IOException if the native invocation raises a checked failure
	 */
	private static int invoke(String operation, MethodHandle function, Object... arguments) throws IOException
	{
		try
		{
			return (int) function.invokeWithArguments(arguments);
		}
		catch (RuntimeException | Error e)
		{
			throw e;
		}
		catch (Throwable e)
		{
			throw new IOException("Native invocation failed: " + operation, e);
		}
	}

	/**
	 * Owns one host-port send right and releases it before the enclosing native scope closes.
	 *
	 * @param release the native port-release function
	 * @param task the borrowed current-task port, which this resource never releases
	 * @param host the acquired host-port send right released by this resource
	 */
	private record HostPort(MethodHandle release, int task, int host) implements AutoCloseable
	{
		/**
		 * Releases the owned host-port send right.
		 *
		 * @throws IOException if native port release fails
		 */
		@Override
		public void close() throws IOException
		{
			int status = invoke("mach_port_deallocate", release, task, host);
			if (status != 0)
				throw new IOException("mach_port_deallocate failed with Mach status " + status);
		}
	}
}

