package oshi.ffm.util.platform.mac;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.ValueLayout;

/** Supplies controlled query outcomes to the public reader without changing the OSHI dependency. */
public final class SysctlUtilFFM {
 /** Returns the selected fixture's physical capacity.
  * @param name the query name
  * @param fallback the unavailable sentinel
  * @return the configured capacity or sentinel
  */
 public static long sysctl(String name,long fallback) {
  if (name.equals("hw.memsize"))
   return System.getProperty("fixture.case").equals("total-unavailable") ? -1 : Long.MAX_VALUE;
  return fallback;
 }
 /** Returns the selected fixture's page size or pressure.
  * @param name the query name
  * @param fallback the unavailable sentinel
  * @return the configured scalar or sentinel
  */
 public static int sysctl(String name,int fallback) {
  String fixture=System.getProperty("fixture.case");
  return switch(name) {
   case "hw.pagesize" -> fixture.equals("page-unavailable") ? -1 : 4096;
   case "kern.memorystatus_vm_pressure_level" -> switch(fixture) {
    case "pressure-unavailable" -> -1;
    case "pressure-invalid" -> 99;
    default -> 1;
   };
   default -> fallback;
  };
 }
 /** Supplies valid zero swap, inconsistent values or an explicit query failure.
  * @param name the query name
  * @param result the caller-owned native result buffer
  * @return true after writing the configured successful observation
  */
 public static boolean sysctl(String name,MemorySegment result) {
  String fixture=System.getProperty("fixture.case");
  if (fixture.equals("swap-unavailable")) return false;
  result.set(ValueLayout.JAVA_LONG,0,0);
  result.set(ValueLayout.JAVA_LONG,16,fixture.equals("swap-invalid") ? 1 : 0);
  return true;
 }
}

