import java.lang.foreign.Linker;
import java.lang.foreign.SymbolLookup;
import java.lang.foreign.ValueLayout;

/** Checks the actual public reader's failure distinction and host-port reference balance. */
class FailureDriver {
 /** Runs controlled query outcomes against the unchanged public reader and real Mach calls.
  * @param args unused
  * @throws Throwable if a native invocation or an assertion fails
  */
 public static void main(String[] args) throws Throwable {
  try (var arena=Arena.ofConfined()) {
   var library=SymbolLookup.libraryLookup("/usr/lib/libSystem.B.dylib",arena);
   var linker=Linker.nativeLinker();
   var hostSelf=linker.downcallHandle(library.find("mach_host_self").orElseThrow(),FunctionDescriptor.of(ValueLayout.JAVA_INT));
   var taskSelf=linker.downcallHandle(library.find("mach_task_self").orElseThrow(),FunctionDescriptor.of(ValueLayout.JAVA_INT));
   var release=linker.downcallHandle(library.find("mach_port_deallocate").orElseThrow(),FunctionDescriptor.of(ValueLayout.JAVA_INT,ValueLayout.JAVA_INT,ValueLayout.JAVA_INT));
   var getRefs=linker.downcallHandle(library.find("mach_port_get_refs").orElseThrow(),FunctionDescriptor.of(ValueLayout.JAVA_INT,ValueLayout.JAVA_INT,ValueLayout.JAVA_INT,ValueLayout.JAVA_INT,ValueLayout.ADDRESS));
   int task=(int)taskSelf.invokeExact();
   int host=(int)hostSelf.invokeExact();
   if (host==0) throw new AssertionError("No fixture-owned host port");
   try {
    var refs=arena.allocate(ValueLayout.JAVA_INT);
    int initialStatus=(int)getRefs.invokeExact(task,host,0,refs);
    if (initialStatus!=0) throw new AssertionError("Initial mach_port_get_refs status "+initialStatus);
    long initialRefs=Integer.toUnsignedLong(refs.get(ValueLayout.JAVA_INT,0));
    String[][] cases={{"total-unavailable","hw.memsize"},{"page-unavailable","hw.pagesize"},
     {"swap-unavailable","vm.swapusage"},{"swap-invalid","Swap capacities"},
     {"pressure-unavailable","memory-pressure flag"},{"pressure-invalid","memory-pressure flag"}};
    for (String[] fixture:cases) {
     System.setProperty("fixture.case",fixture[0]);
     try { throw new AssertionError("Public reader accepted invalid fixture: "+MacMemory.read()); }
     catch (IOException expected) {
      if (!expected.getMessage().contains(fixture[1])) throw new AssertionError("Wrong failure context",expected);
      System.out.println("rejected="+fixture[0]+":"+expected.getMessage());
     }
     int status=(int)getRefs.invokeExact(task,host,0,refs);
     long currentRefs=Integer.toUnsignedLong(refs.get(ValueLayout.JAVA_INT,0));
     if (status!=0 || currentRefs!=initialRefs) throw new AssertionError("Host send-right imbalance: "+status+":"+initialRefs+":"+currentRefs);
     System.out.println("balanced="+fixture[0]+":refs="+currentRefs);
    }
    System.setProperty("fixture.case","zero-swap");
    var sample=MacMemory.read();
    if (sample.swapTotalBytes()!=0 || sample.swapUsedBytes()!=0 || sample.pressure()!=MacMemory.Pressure.NORMAL)
     throw new AssertionError("Valid zero swap rejected or altered: "+sample);
    int finalStatus=(int)getRefs.invokeExact(task,host,0,refs);
    long finalRefs=Integer.toUnsignedLong(refs.get(ValueLayout.JAVA_INT,0));
    if (finalStatus!=0 || finalRefs!=initialRefs) throw new AssertionError("Success leaked a host send right");
    System.out.println("accepted-zero-swap="+sample+":refs="+finalRefs);
   } finally {
    int status=(int)release.invokeExact(task,host);
    if (status!=0) throw new AssertionError("Fixture-owned host-port cleanup status "+status);
   }
  }
  System.out.println("MAC_MEMORY_PUBLIC_FAILURE_AND_CLEANUP_PASSED");
 }
}

