import java.io.IOException;
import java.nio.file.Path;

/**
 * Exercises the integrated named tooling module on the local Linux host.
 */
class MemoryIntegrationProbe
{
    /**
     * Acquires real Linux counters and verifies the Windows platform guard and macOS sample contract.
     *
     * @param arguments unused diagnostic arguments
     * @throws IOException if Linux host sampling fails
     */
    public static void main(String[] arguments) throws IOException
    {
        var module = WindowsMemory.class.getModule();
        System.out.println("module=" + module.getName());
        System.out.println("module-source=" + module.getLayer().configuration()
            .findModule(module.getName()).orElseThrow().reference().location().orElseThrow());
        var linux = LinuxMemory.read(Path.of("/proc"));
        System.out.println("linux=" + linux);
        try
        {
            WindowsMemory.read();
            throw new AssertionError("WindowsMemory must reject Linux");
        }
        catch (UnsupportedOperationException expected)
        {
            System.out.println("windows-platform-guard=" + expected.getMessage());
        }
        try
        {
            new MacMemory.Sample(1, 0, 0, 0, null);
            throw new AssertionError("Sample must reject absent pressure");
        }
        catch (NullPointerException expected)
        {
            System.out.println("mac-sample-guard=" + expected.getMessage());
        }
        System.out.println("INTEGRATED_MEMORY_MODULE_PASSED");
    }
}
